class.description:
Every child's [member Node.multiplayer] is this tree's [member api], as with [method SceneTree.set_multiplayer]. Two trees in one [SceneTree] are two separate sessions, such as a server and a client in one process. [codeblock] tree.peer_class = &"ENetMultiplayerPeer" tree.transport_settings = { port = 21253 }
# assign a peer as usual var peer := ENetMultiplayerPeer.new() peer.create_client("127.0.0.1", 21253) tree.api.session_prepare_join(&"PlayerOne", []) tree.api.multiplayer_peer = peer
# or let the transport create it Netw.connection(tree).create_peer( tree.peer_class, NetwMultiplayer.TRANSPORT_MODE_CLIENT, "127.0.0.1:21253", tree.transport_settings, func(peer: MultiplayerPeer, error: Error, _detail: String) -> void: if error == OK: tree.api.session_prepare_join(&"PlayerOne", []) tree.api.multiplayer_peer = peer, ) [/codeblock]
